do $$declare f jsonb; d jsonb; p jsonb; c jsonb; v jsonb; t jsonb; s jsonb; st jsonb; o jsonb; clone jsonb; rule jsonb; prereq jsonb; empty_version jsonb; audit_count bigint;
begin
  perform test.login(1);
  perform test.expect('PT400','createFaculty','{}','{}');
  perform test.expect('PT400','createFaculty','{}','{"name":"Faculty","actor_id":"spoof"}');
  perform test.expect('PT400','updateFaculty','{"id":"invalid"}','{"name":"Faculty"}');
  perform test.expect('PT404','updateFaculty','{"id":"ffffffff-0000-4000-8000-000000000000"}','{"name":"Faculty"}');
  f:=test.call('createFaculty','{}','{"name":"Test Faculty A","code":"FA"}');
  perform test.call('updateFaculty',jsonb_build_object('id',f->>'id'),'{"letterhead_prefix":"Dean"}');
  perform test.expect('PT409','createFaculty','{}','{"name":" test faculty a "}');
  d:=test.call('createDepartment','{}',jsonb_build_object('faculty_id',f->>'id','name','Test Department A'));
  perform test.call('updateDepartment',jsonb_build_object('id',d->>'id'),'{"code":"DA"}');
  perform test.expect('PT409','deleteFaculty',jsonb_build_object('id',f->>'id'));
  p:=test.call('createProgram','{}',jsonb_build_object('department_id',d->>'id','code','TST','name','Test Program','nominal_duration',4));
  perform test.call('updateProgram',jsonb_build_object('id',p->>'id'),'{"name":"Test Program Updated"}');
  perform test.expect('PT409','deleteDepartment',jsonb_build_object('id',d->>'id'));
  v:=test.call('createCurriculumVersion','{}',jsonb_build_object('program_id',p->>'id','version_label','2026','effective_start','2026-01-01','delinquency_threshold',12));
  perform test.assert((v->>'total_units')::numeric=0,'empty draft total');
  t:=test.call('createCurriculumTerm','{}',jsonb_build_object('curriculum_version_id',v->>'id','year_level',1,'term_sequence',1));
  perform test.call('updateCurriculumTerm',jsonb_build_object('id',t->>'id'),'{"term_sequence":2}');
  c:=test.call('createCourse','{}',jsonb_build_object('department_id',d->>'id','code','TST101','title','Test Course','units',3));
  perform test.call('updateCourse',jsonb_build_object('id',c->>'id'),'{"title":"Updated Course"}');
  s:=test.call('createCurriculumTermCourse','{}',jsonb_build_object('curriculum_term_id',t->>'id','course_id',c->>'id','is_elective_slot',false,'nominal_units',3));
  perform test.call('updateCurriculumTermCourse',jsonb_build_object('id',s->>'id'),'{"nominal_units":4}');
  perform test.call('updateCurriculumTerm',jsonb_build_object('id',t->>'id'),'{"year_level":2}');
  perform test.assert((select total_units=4 from public.curriculum_version where id=(v->>'id')::uuid),'computed units');
  perform test.call('updateCurriculumVersion',jsonb_build_object('id',v->>'id'),'{"status":"active"}');
  clone:=test.call('createCurriculumVersion','{}',jsonb_build_object('program_id',p->>'id','version_label','clone','effective_start','2026-01-01','clone_from_version_id',v->>'id'));
  perform test.assert((clone->>'total_units')::numeric=4,'cloned units');
  empty_version:=test.call('createCurriculumVersion','{}',jsonb_build_object('program_id',p->>'id','clone_from_version_id',v->>'id','curriculum',jsonb_build_object('version_label','nested clone','effective_start','2026-01-01','delinquency_threshold',12,'total_units',4,'terms','[]'::jsonb)));
  perform test.assert((empty_version->>'total_units')::numeric=4,'nested-definition clone units');
  perform test.call('deleteCurriculumVersion',jsonb_build_object('id',empty_version->>'id'));
  rule:=test.call('createCurriculumPairEquivalence','{}',jsonb_build_object('from_curriculum_version_id',v->>'id','to_curriculum_version_id',clone->>'id','source_course_id',c->>'id','target_course_id',c->>'id'));
  perform test.call('deleteCurriculumPairEquivalence',jsonb_build_object('id',rule->>'id'));
  perform test.expect('PT400','createPrerequisite','{}',jsonb_build_object('course_id',c->>'id','prerequisite_course_id',c->>'id','type','strict'));
  empty_version:=test.call('createCourse','{}',jsonb_build_object('department_id',d->>'id','code','TEMP101','title','Temporary Course','units',3));
  prereq:=test.call('createPrerequisite','{}',jsonb_build_object('course_id',c->>'id','prerequisite_course_id',empty_version->>'id','type','recommended'));
  perform test.call('deletePrerequisite',jsonb_build_object('id',prereq->>'id'));
  perform test.call('deleteCourse',jsonb_build_object('id',empty_version->>'id'));
  empty_version:=test.call('createCurriculumTermCourse','{}',jsonb_build_object('curriculum_term_id',t->>'id','is_elective_slot',true,'slot_label','Temporary Elective','nominal_units',0));
  perform test.call('deleteCurriculumTermCourse',jsonb_build_object('id',empty_version->>'id'));
  empty_version:=test.call('createCurriculumTerm','{}',jsonb_build_object('curriculum_version_id',v->>'id','year_level',2,'term_sequence',1));
  perform test.call('deleteCurriculumTerm',jsonb_build_object('id',empty_version->>'id'));
  empty_version:=test.call('createCurriculumVersion','{}',jsonb_build_object('program_id',p->>'id','version_label','temporary','effective_start','2026-01-01'));
  perform test.call('deleteCurriculumVersion',jsonb_build_object('id',empty_version->>'id'));
  empty_version:=test.call('createProgram','{}',jsonb_build_object('department_id',d->>'id','code','TMP','name','Temporary Program','nominal_duration',1));
  perform test.call('deleteProgram',jsonb_build_object('id',empty_version->>'id'));
  empty_version:=test.call('createDepartment','{}',jsonb_build_object('faculty_id',f->>'id','name','Temporary Department'));
  perform test.call('deleteDepartment',jsonb_build_object('id',empty_version->>'id'));
  empty_version:=test.call('createFaculty','{}','{"name":"Temporary Faculty"}');
  perform test.call('deleteFaculty',jsonb_build_object('id',empty_version->>'id'));
  st:=test.call('createSchoolTerm','{}','{"start_year":2026,"end_year":2027,"term_type":"1st Semester","ends_on":"2026-12-01"}');
  perform test.call('updateSchoolTerm',jsonb_build_object('id',st->>'id'),'{"encoding_deadline":"2026-12-02"}');
  o:=test.call('createCourseOffering','{}',jsonb_build_object('school_term_id',st->>'id','course_id',c->>'id','section','A'));
  perform test.call('updateCourseOffering',jsonb_build_object('id',o->>'id'),'{"instructor":"Test Instructor"}');
  empty_version:=test.call('createCourseOffering','{}',jsonb_build_object('school_term_id',st->>'id','course_id',c->>'id','section','TEMP'));
  perform test.call('deleteCourseOffering',jsonb_build_object('id',empty_version->>'id'));
  perform test.expect('PT409','updateSchoolTerm',jsonb_build_object('id',st->>'id'),'{"start_year":2025}');
  perform test.expect('PT409','deleteCourse',jsonb_build_object('id',c->>'id'));
  select count(*) into audit_count from public.audit_log_entry;
  perform test.expect('PT409','createCourse','{}',jsonb_build_object('department_id',d->>'id','code','ROLLBACK','title','Must Roll Back','units',3,'initial_curriculum_slot',jsonb_build_object('curriculum_version_id','ffffffff-0000-4000-8000-000000000000','year_level',1,'term_sequence',1)));
  perform test.assert(not exists(select 1 from public.course where code='ROLLBACK'),'nested course rollback');
  perform test.assert((select count(*)=audit_count from public.audit_log_entry),'audit rolled back');
  insert into test.records values('faculty',f),('department',d),('program',p),('course',c),('version',v),('term',t),('slot',s),('target_version',clone),('school_term',st),('offering',o);
end$$;
